{% assign defaultlang = settings['LanguageLocale/Code'] | default: 'en-us' %}
{% assign homeurl = website.adx_partialurl %}
<div class='navbar navbar-inverse navbar-static-top' role='banner'>
  <div class='skip-to-content'>
    <a href='#mainContent'>{{ resx.Skip_To_Content | default: 'Skip to main content' }}</a>
  </div>
  <div class='header-container'>
    <div class='navbar-header'>
      <!--
        div class="visible-xs-block">
          {% editable snippets 'Mobile Header' type: 'html' %}
        </div
      -->
      <div class='visible-sm-block visible-md-block visible-lg-block visible-xs-block navbar-brand'>
        {% editable snippets 'Mobile Header' type: 'html' %}
      </div>
      <button
        type='button'
        class='navbar-toggle collapsed'
        title='{{ snippets["Header/Toggle Navigation"] | default: resx['Toggle_Navigation'] | h }}'
        data-toggle='collapse'
        data-target='#navbar'
        aria-expanded='false'
        onclick='setHeight();'
      >
        <span class='sr-only'>
          {{- snippets['Header/Toggle Navigation'] | default: resx.Toggle_Navigation | h -}}
        </span>
        <span class='icon-bar'></span>
        <span class='icon-bar'></span>
        <span class='icon-bar'></span>
      </button>
    </div>
    <div id='navbar' class='navbar-collapse collapse'>
      {% assign primary_nav = weblinks.Default %}
      {% if primary_nav %}
        <nav
          aria-label='{{ resx.Main_Navigation | default: "Main Navigation" }}'
          class='navbar-right menu-bar {% if primary_nav.editable %}xrm-entity xrm-editable-adx_weblinkset{% endif %}'
          data-weblinks-maxdepth='2'
        >
          <ul class='nav navbar-nav weblinks'>
            {% for link in primary_nav.weblinks %}
              {% unless forloop.first %}
                <li class='divider-vertical' aria-hidden='true'></li>
              {% endunless %}
              {% if link.display_page_child_links %}
                {% if link.url != null %}
                  {% assign sublinks = sitemap[link.url].children %}
                {% endif %}
              {% else %}
                {% assign sublinks = link.weblinks %}
              {% endif %}
              <li class='weblink {% if sublinks.size > 0 %} dropdown{% endif %}'>
                <a
                  aria-label='{{ link.name | escape }}'
                  {% if sublinks.size > 0 -%}
                    href='#' role='button' class='dropdown-toggle' data-toggle='dropdown'
                  {%- else -%}
                    href='{{ link.url | escape }}' aria-roledescription='link'
                  {%- endif -%}
                  {%- if link.Open_In_New_Window %}
                    target='_blank'
                  {% endif -%}
                  {%- if link.nofollow %}
                    rel='nofollow'
                  {% endif -%}
                  {%- if link.tooltip %}
                    title='{{ link.tooltip | escape }}'
                  {% endif %}
                >
                  {%- if link.image -%}
                    {%- if link.image.url -%}
                      {%- if link.image.url.first == '.' -%}
                        <span class='{{ link.image.url | split:'.' | join }}' aria-hidden='true'></span>
                      {%- endif -%}
                    {%- else -%}
                      <img
                        src='{{ link.image.url | escape }}'
                        alt='{{ link.image.alternate_text | default:link.tooltip | escape }}'
                        {% if link.image.width %}
                          width='{{ link.image.width | escape }}'
                        {% endif %}
                        {% if link.image.height %}
                          height='{{ link.image.height | escape }}'
                        {% endif %}
                      >
                    {%- endif -%}
                  {%- endif -%}
                  {%- unless link.display_image_only -%}
                    {{ link.name | escape }}
                  {%- endunless -%}
                  {%- if sublinks.size > 0 -%}
                    <span class='caret'></span>
                  {%- endif -%}
                </a>
                {% if sublinks.size > 0 %}
                  <ul class='dropdown-menu'>
                    {% if link.name %}
                      <li>
                        <a
                          aria-label='{{ link.name | escape }}'
                          aria-roledescription='link'
                          href='{{ link.url }}'
                          {% if link.Open_In_New_Window %}
                            target='_blank'
                          {% endif %}
                          {% if link.nofollow %}
                            rel='nofollow'
                          {% endif %}
                          {% if link.tooltip %}
                            title='{{ link.tooltip | escape }}'
                          {% endif %}
                        >
                          {{- link.name | escape -}}
                        </a>
                      </li>
                      <div class='divider'></div>
                    {% endif %}
                    {% for sublink in sublinks %}
                      <li>
                        <a
                          aria-label='{{ sublink.name | default:sublink.title | escape }}'
                          aria-roledescription='link'
                          href='{{ sublink.url }}'
                          {% if sublink.Open_In_New_Window %}
                            target='_blank'
                          {% endif %}
                          {% if sublink.nofollow %}
                            rel='nofollow'
                          {% endif %}
                          {% if sublink.tooltip %}
                            title='{{ sublink.tooltip | escape }}'
                          {% endif %}
                        >
                          {{ sublink.name | default: sublink.title | escape }}
                        </a>
                      </li>
                    {% endfor %}
                  </ul>
                {% endif %}
              </li>
            {% endfor %}
            {% assign search_enabled = settings['Search/Enabled'] | boolean | default: true %}
            {% if search_enabled %}
              <li class='divider-vertical' aria-hidden='true'></li>
              <li class='dropdown'>
                <a
                  id='search'
                  class='navbar-icon'
                  href='#'
                  data-toggle='dropdown'
                  role='button'
                  aria-expanded='false'
                  aria-label='{{ snippets["Header/Search/ToolTip"] | default:resx["Search_DefaultText"] | escape }}'
                >
                  <span class='glyphicon glyphicon-search'></span>
                </a>
                <div class='dropdown-menu dropdown-search'>
                  {% include 'Search', search_id: 'q' %}
                </div>
              </li>
            {% endif %}

            {% if website.languages.size > 1 %}
              <li class='divider-vertical' aria-hidden='true'></li>
              <li class='dropdown'>
                <a
                  class='dropdown-toggle'
                  aria-roledescription='link'
                  href='#'
                  data-toggle='dropdown'
                  aria-label='{{ website.selected_language.name | escape }}'
                  aria-haspopup='true'
                  aria-expanded='false'
                  title='{{ website.selected_language.name | escape }}'
                >
                  <span class='drop_language'>{{ website.selected_language.name | escape }}</span>
                  <span class='caret'></span>
                </a>
                {% include 'Languages Dropdown' %}
              </li>
            {% endif %}

            {% assign profile_enabled = settings['Profile/Enabled'] | boolean | default: true %}
            {% if profile_enabled %}
              <li class='divider-vertical' aria-hidden='true'></li>
              {% if user %}
                <li class='dropdown'>
                  {% assign username = user.fullname | escape %}
                  <a
                    href='#'
                    class='dropdown-toggle'
                    aria-roledescription='link'
                    title='{{username | default: resx['Default_Profile_name'] }}'
                    data-toggle='dropdown'
                    role='button'
                    aria-expanded='false'
                  >
                    <span class='username'>{{ username | default: resx.Default_Profile_name }}</span>
                    <span class='caret'></span>
                  </a>
                  <ul class='dropdown-menu'>
                    {% assign show_profile_nav = settings['Header/ShowAllProfileNavigationLinks'] | boolean | default: true %}
                    {% if show_profile_nav %}
                      {% assign profile_nav = weblinks['Profile Navigation'] %}
                      {% if profile_nav %}
                        {% for link in profile_nav.weblinks %}
                          <li>
                            <a
                              aria-label='{{ link.name | escape }}'
                              aria-roledescription='link'
                              href='{{ link.url | escape }}'
                              title='{{ link.name | escape }}'
                            >
                              {{- link.name | escape -}}
                            </a>
                          </li>
                        {% endfor %}
                      {% endif %}
                    {% else %}
                      <li>
                        <a
                          aria-label='{{ snippets["Profile Link Text"] | default:resx["Profile_Text"] | escape }}'
                          aria-roledescription='link'
                          href='{{ sitemarkers['Profile'].url | escape }}'
                        >
                          {{- snippets['Profile Link Text'] | default: resx.Profile_Text | escape -}}
                        </a>
                      </li>
                    {% endif %}
                    <li class='divider' role='separator' aria-hidden='true'></li>
                    <li>
                      <a
                        aria-label='{{ snippets["links/logout"] | default:resx["Sign_Out"] | escape }}'
                        aria-roledescription='link'
                        href='{% if homeurl%}/{{ homeurl }}{% endif %}{{ website.sign_out_url_substitution }}'
                        title='{{ snippets["links/logout"] | default:resx["Sign_Out"] | escape }}'
                      >
                        {{ snippets['links/logout'] | default: resx.Sign_Out | escape }}
                      </a>
                    </li>
                  </ul>
                </li>
              {% else %}
                <li>
                  <a
                    aria-label='{{ snippets["links/login"] | default:resx["Sign_In"] | escape }}'
                    aria-roledescription='link'
                    href='{% if homeurl%}/{{ homeurl }}{% endif %}{{ website.sign_in_url_substitution }}'
                    class='loginBtn'
                  >
                    {{ snippets['links/login'] | default: resx.Sign_In | escape }}
                  </a>
                </li>
              {% endif %}
            {% endif %}
          </ul>
          {% editable primary_nav %}
        </nav>
      {% endif %}
    </div>
  </div>
</div>
{% substitution %}
{% assign current_page = page.id %}
{% assign sr_page = sitemarkers.Search.id %}
{% assign forum_page = sitemarkers.Forums.id %}
{% if current_page %}
  {% if current_page == sr_page or current_page == forum_page %}
    {% assign section_class = 'section-landing-search' %}
    {% if current_page == forum_page %}
      {% assign section_class = 'section-landing-forums' %}
    {% endif %}
    <section class='page_section {{ section_class | h }} color-inverse'>
      <div
        class='row sectionBlockLayout sectionFixedStyle'
        style='display: flex; flex-wrap: wrap; text-align: center;'
      >
        <div class='container' style='display: flex; flex-wrap: wrap;'>
          <div
            class='col-md-12 columnBlockLayout'
            style='display: flex; flex-direction: column; justify-content: center;'
          >
            {% if current_page == sr_page %}
              <h1 id='mainContent'>
                {% editable snippets 'Search/Title' default: resx["Discover_Contoso"] %}
              </h1>
              {% include 'Search', search_id: 'search_control' %}
            {% endif %}
          </div>
        </div>
      </div>
    </section>
  {% endif %}
{% endif %}
{% endsubstitution %}
<script type='text/javascript'>
  window.onload = function () {
    if (window.navigator.appName == 'Microsoft Internet Explorer' || window.navigator.userAgent.indexOf('Trident') > 0) {
      var searchElement = document.getElementById('search');
      if (searchElement != null) searchElement.setAttribute('href', '');
    }
  };
  function setHeight() {
    var windowHeight = window.innerHeight - 140;
    var navbar = document.getElementById('navbar');
    if (navbar) {
      navbar.style.maxHeight = windowHeight + 'px';
    }
  }
  window.addEventListener('resize', function (event) {
    setHeight();
  });
</script>

{% assign current_page = current_page | default: 1 %}
{% assign page_size = page_size | default: 10 %}
{% assign total = total | default: 0 %}
{% assign limit = 5 %}

{% assign total_pages_remainder = total | modulo: page_size %}
{% if total_pages_remainder > 0 %}
  {% assign total_pages = total | divided_by: page_size | plus: 1 %}
{% else %}
  {% assign total_pages = total | divided_by: page_size %}
{% endif %}

{% if total_pages > 1 %}
  {% assign prev_page = current_page | minus: 1 %}
  {% assign next_page = current_page | plus: 1 %}

  {% assign start_page = 0 %}
  {% assign offset = limit | divided_by: 2 %}
  {% assign page_offset = current_page | minus: 1 %}
  {% if page_offset > offset %}
    {% assign start_page = current_page | minus: offset | minus: 1 %}
  {% endif %}

  <ul class='pagination'>
    {% if current_page == 1 %}
      <li class='disabled'>
        <a href='{{ request.url | add_query: 'page', '1' | path_and_query | escape }}'>«</a>
      </li>
      <li class='disabled'>
        <a href='{{ request.url | add_query: 'page', prev_page | path_and_query | escape }}'>‹</a>
      </li>
    {% else %}
      <li><a href='{{ request.url | add_query: 'page', '1' | path_and_query | escape }}'>«</a></li>
      <li>
        <a href='{{ request.url | add_query: 'page', prev_page | path_and_query | escape }}'>‹</a>
      </li>
    {% endif %}

    {% for page in (1..total_pages) offset: start_page limit: limit %}
      <li
        {% if page == current_page %}
          class='active'
        {% endif %}
      >
        <a href='{{ request.url | add_query:'page', page | path_and_query | escape }}'> {{ page }}</a>
      </li>
    {% endfor -%}

    {% if current_page == total_pages %}
      <li class='disabled'><a href='#' aria-label='Next'>›</a></li>
      <li class='disabled'><a href='#' aria-label='Last'>»</a></li>
    {% else %}
      <li>
        <a href='{{ request.url | add_query: 'page', next_page | path_and_query | escape }}'>›</a>
      </li>
      <li>
        <a href='{{ request.url | add_query: 'page', total_pages | path_and_query | escape }}'>»</a>
      </li>
    {% endif %}
  </ul>
{% endif %}

{%manifest%}
{
  "type":"functional",
  "displayName": "Search Results Headings",
  "tables": ["faq_topic", "faq_article"],
  "params":[
      {
         "id":"articles_query_text",
         "displayName":"Articles results heading",
         "description":"The heading that will be displayed when there are results for articles"
      },
       {
         "id":"topics_query_text",
         "displayName":"Topics results heading",
         "description":"The heading that will be displayed when there are results for headings"
      }
  ]
}
{%endmanifest%}

{% assign searchQuery = request.params.search %}

{% fetchxml topics %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_topic'>
    <attribute name='faq_topicid' />
    <attribute name='faq_topictitle' />
    <attribute name='faq_topicicon' />
    <filter type='and'>
      <condition attribute='faq_topictitle' operator='like' value='%{{searchQuery}}%' />
      <condition attribute='faq_publishedstatus' operator='eq' value='1' />
      <condition attribute='faq_parenttopic' operator='null' />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}
{% if topics.results and topics.results.entities and topics.results.entities.size > 0 %}
  {% assign entityCode = topics.results.entities[0].objecttypecode %}
  {% assign topicsFound = true %}
{% endif %}
{% assign topicsResult = topics.results.entities %}

{% fetchxml articles %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_article'>
    <attribute name='faq_articleid' />
    <attribute name='faq_articletitle' />
    <link-entity name='faq_topic' from='faq_topicid' to='faq_topic' link-type='inner' alias='ab' />
    <filter>
      <condition attribute='faq_publishedstatus' operator='eq' value='1' />
    </filter>
    <filter type='or'>
      <condition attribute='faq_articletitle' operator='like' value='%{{searchQuery}}%' />
      <condition attribute='faq_articlebody' operator='like' value='%{{searchQuery}}%' />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}
{% if articles.results and articles.results.entities and articles.results.entities.size > 0 %}
  {% assign articlesResult = articles.results.entities %}
  {% assign articlesFound = true %}
{% endif %}

<div class='search-categories-container'>
  {% if topicsFound == true %}
    <div>
      <h1 style='margin-bottom: 16px;'>{{ topics_query_text | default: "Topics found for query" }} "{{searchQuery}}"</h1>
      <ul class='category-list'>
        {% for topic in topicsResult %}
          {% if topic.faq_topicicon.Url == null %}
            <li class='category-list-item'>
              <a style='color: #000 !important;' href='/topics/?q={{topic.faq_topicid}}' class='category-list-title-active'>{{ topic.faq_topictitle }}</a>
            </li>
          {% else %}
            {% unless topic.faq_parenttopic == empty %}
              {% if topic.faq_topicid == request.params.q %}
                <li class='category-list-item'>
                  <img src='{{topic.faq_topicicon.Url}}' alt='' class='list-icon'> <a href='/topics/?q={{topic.faq_topicid}}' class='category-list-title-active'>{{ topic.faq_topictitle }}</a>
                </li>
              {% else %}
                <li class='category-list-item'>
                  <img src='{{topic.faq_topicicon.Url}}' alt='' class='list-icon'> <a href='/topics/?q={{topic.faq_topicid}}' class='category-list-title'>{{ topic.faq_topictitle }}</a>
                </li>
              {% endif %}
            {% endunless %}
          {% endif %}
        {% endfor %}
      </ul>
    </div>
  {% else %}
    <div>
      <h1 style='margin-bottom: 16px;'>{% include 'snippet', snippet_name: 'NoTopic' %}</h1>
    </div>
  {% endif %}
  {% if articlesFound == true %}
    <div>
      <h1 style='margin-bottom: 16px;'>{{ articles_query_text | default: "Articles found for query" }} "{{searchQuery}}"</h1>
      <ul class='category-list-ul'>
        {% for article in articlesResult %}
          <li>
            <a href='/articles/?q={{article.faq_articleid}}&t={{article.faq_faq_article_Topic_faq_topic.faq_topicid}}' class='category-a'>{{ article.faq_articletitle }}</a>
          </li>
        {% endfor %}
      </ul>
    </div>
    {% else %}
    <div>
      <h1 style='margin-bottom: 16px;'>{% include 'snippet', snippet_name: 'NoArticle' %}</h1>
    </div>
  {% endif %}
</div>

{% extends 'Layout 2 Column Wide Left' %}

{% block title %}
{% assign rt = snippets['Search/ResultsTitle'] %}
{% if rt %}
  {% assign title = rt | liquid %}
{% else %}
  {% assign title = rt %}
{% endif %}
{% assign title = title | truncate: 115 %}
{% include 'Page Header', title: title %}
{% endblock %}

{% block main %}
{% assign page_size = 10 %}
{% assign current_page = request.params.page | default: 1 %}
{% searchindex query: request.params.q, page: request.params.page, page_size: page_size %}
{% if searchindex.results.size > 0 %}
  <p class='result-count'>
    {% assign rc = snippets['Search/ResultsCount'] -%}
    {%- if rc -%}
      {{- rc | liquid -}}
    {%- else -%}
      {{- current_page }} - {{ page_size }} of {{ searchindex.approximate_total_hits }} Results test
    {%- endif %}
  </p>
  <ul class='search-results'>
    {% for result in searchindex.results %}
      <li>
        <h4>
          <a title='{{ result.title | escape }}' href='{{ result.url | escape }}'>
            {{- result.title | escape -}}
          </a>
        </h4>
        <p class='fragment'>{{ result.fragment }}</p>
      </li>
    {% endfor %}
  </ul>
  {% include 'Pagination', current_page: searchindex.page, page_size: page_size, total: searchindex.approximate_total_hits %}
{% else %}
  {{ snippets['Search/NoResults'] }}
{% endif %}
{% endsearchindex %}
{% endblock %}

{%manifest%}
{
  "type":"functional",
  "displayName": "Topics",
  "tables": ["faq_topic"],
  "params":[
      {
         "id":"num_cards",
         "displayName":"How many cards should be displayed?",
         "description":"The max number of topics cards that the user will see"
      }
  ]
}
{%endmanifest%}

<!-- Get Application types set values -->
{% fetchxml topics %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_topic'>
    <attribute name='faq_topicicon' />
    <attribute name='faq_topictitle' />
    <attribute name='faq_topicid' />
    <order attribute='faq_topicorder' descending='false' />
    <filter type='and'>
      <condition attribute='faq_parenttopic' operator='null' />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}
<script>
  $(document).ready(function () {
    $('#moreTopics').hide();
    $('#showLess').hide();

    $('#showMore').click(function () {
      $('#moreTopics').show();
      $('#showLess').show();
      $('#showMore').hide();
    });

    $('#showLess').click(function () {
      $('#moreTopics').hide();
      $('#showLess').hide();
      $('#showMore').show();
    });

    $('.show-link-container').css({
      display: 'flex',
      'justify-content': 'center',
    });

    $('.show-topics-link').css({
      color: '#0E51CB',
      'font-weight': 'bold',
      'font-family': 'sans-serif',
      'text-align': 'center',
      'font-size': '20px',
      'max-width': '600px',
      position: 'relative',
    });

    $('.left-line').css({
      content: '',
      display: 'block',
      width: '30em',
      height: '1px',
      background: '#000',
      'margin-top': '12px',
      'margin-right': '12px',
    });

    $('.right-line').css({
      content: '',
      display: 'block',
      width: '30em',
      height: '1px',
      background: '#000',
      'margin-top': '12px',
      'margin-left': '12px',
    });

    $('.topicsContainer').css({
      'justify-content': 'start',
    });

    $('.show-link-container').css({
      'margin-bottom': '5em',
    });
  });

  function updateTopic(appName) {
    var queryUrl = '/topics/?q=';
    queryUrl = queryUrl + appName.replaceAll(' ', '-');
    window.location.href = queryUrl;
  }

  function selectTopic(topicId) {
    if (event.keyCode == 13) {
      window.location.href = '/topics/?q=' + topicId;
    }
  }
</script>
{% if topics.results and topics.results.entities and topics.results.entities.size > 0 %}
  {% assign entityCode = topics.results.entities[0].objecttypecode %}
{% endif %}
{% assign topicsResult = topics.results.entities %}

{% assign topicsCount = num_cards | integer | default: 6 %}

<h2 id='topic-container-header' tabindex='0'>Topics</h2>
<div class='topicsContainer'>
  {% for topic in topicsResult limit: topicsCount %}
    <a onclick="updateTopic('{{topic.faq_topicid}}')" onkeypress="selectTopic('{{topic.faq_topicid}}')" class='topic' data-component-theme='portalThemeColor7' value='{{topic.attributevalue}}' tabindex='0' aria-label='{{topic.faq_topictitle}}'>
      <img class='topicIcon' src='home-icon.png' alt='topic icon'>
      {% unless topic.faq_topictitle == empty %}
        <h2 class='topicTitle'>{{ topic.faq_topictitle }}</h2>
      {% endunless %}
    </a>
  {% endfor %}
</div>

{% if topics.results.entities.size > topicsCount %}
  <div class='show-link-container'>
    <span class='left-line'></span>
    <div id='showMore' class='show-topics-link'>
      {{ snippets['Show more'] }}
      <span class='fa fa-chevron-circle-down fa-fw' aria-hidden='true'></span>
    </div>
    <div id='showLess' class='show-topics-link'>
      {{ snippets['Show less'] }}
      <span class='fa fa-chevron-circle-up fa-fw' aria-hidden='true'></span>
    </div>
    <span class='right-line'></span>
  </div>
{% endif %}

<div id='moreTopics' class='topicsContainer'>
  {% for topic in topicsResult offset: topicsCount %}
    <a onclick="updateTopic('{{topic.faq_topicid}}')" class='topic' data-component-theme='portalThemeColor7' value='{{topic.attributevalue}}'>
      <img class='topicIcon' src='home-icon.png' alt='topic icon'>
      {% unless topic.faq_topictitle == empty %}
        <h2 class='topicTitle'>{{ topic.faq_topictitle }}</h2>
      {% endunless %}
    </a>
  {% endfor %}
</div>

{% fetchxml topics %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_topic'>
    <attribute name='faq_topictitle' />
    <attribute name='faq_topicicon' />
    <attribute name='faq_topicid' />
    <attribute name='faq_parenttopic' />
    <filter type='and'>
      <condition attribute='faq_parenttopic' operator='null' />
    </filter>
    <order attribute='faq_topicorder' descending='false' />
  </entity>
</fetch>
{% endfetchxml %}
{% if topics.results and topics.results.entities and topics.results.entities.size > 0 %}
  {% assign entityCode = topics.results.entities[0].objecttypecode %}
{% endif %}
{% assign topicsResult = topics.results.entities %}

{% for topic in topicsResult %}
  {% if topic.faq_topicid == request.params.q %}
    {% assign topicName = topic.faq_topictitle %}
    {% assign topicID = topic.faq_topicid %}
  {% endif %}
{% endfor %}
{% assign searchQuery = request.params.search %}

{% fetchxml subtopics %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_topic'>
    <attribute name='faq_topictitle' />
    <attribute name='faq_topicicon' />
    <attribute name='faq_topicid' />
    <attribute name='faq_parenttopic' />
    <filter type='and'>
      <condition attribute='faq_parenttopic' operator='eq' value='{{topicID}}' uiname='{{topicName}}' uitype='faq_topic' />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}
{% if subtopics.results and subtopics.results.entities and subtopics.results.entities.size > 0 %}
  {% assign entityCode = subtopics.results.entities[0].objecttypecode %}
{% endif %}
{% assign subTopicsResult = subtopics.results.entities %}

{% fetchxml articles %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_article'>
    <attribute name='faq_articletitle' />
    <attribute name='faq_articleid' />
    <link-entity name='faq_topic' from='faq_topicid' to='faq_topic' link-type='inner' alias='ab' />
    <filter type='and'>
      <condition attribute='faq_publishedstatus' operator='eq' value='1' />
    </filter>
    <order attribute='faq_featuredarticleorder' descending='false' />
  </entity>
</fetch>
{% endfetchxml %}
{% if articles.results and articles.results.entities and articles.results.entities.size > 0 %}
  {% assign articlesResult = articles.results.entities %}
{% endif %}

{% fetchxml parentArticles %}
<fetch version='1.0' output-format='xml-platform' mapping='logical'>
  <entity name='faq_article'>
    <attribute name='faq_articletitle' />
    <attribute name='faq_topic' />
    <attribute name='faq_articleid' />
    <link-entity name='faq_topic' from='faq_topicid' to='faq_topic' link-type='inner'>
      <filter type='and'>
        <condition attribute='faq_publishedstatus' operator='eq' value='1' />
        <condition attribute='faq_topicid' operator='eq' value='{{topicID}}' />
      </filter>
    </link-entity>
  </entity>
</fetch>
{% endfetchxml %}
{% if parentArticles.results and parentArticles.results.entities and parentArticles.results.entities.size > 0 %}
  {% assign parentArticlesExist = true %}
{% else %}
  {% assign parentArticlesExist = false %}
{% endif %}

<div class='categories-container'>
  <div class='category-list-container'>
    <a href='/' class='category-list-a'> <img id='img-back-breadcrumb' alt='back breadcrumb' src='/back-breadcrumb.png'>Back to Topics</a>
    <hr style='margin: 48px 0;'>
    <ul class='category-list'>
      {% for topic in topicsResult %}
        {% if topic.faq_topicicon.Url == empty %}
          <li class='category-list-item'>
            <a href='/topics/?q={{topic.faq_topicid}}' aria-current='page' aria-label='{{ topic.faq_topictitle }} link current page' class='category-list-title-active'>{{ topic.faq_topictitle }}</a>
          </li>
        {% else %}
          {% if topic.faq_topicid == request.params.q %}
            <li class='category-list-item'>
              <img src='{{topic.faq_topicicon.Url}}' aria-current='page' alt='{{ topic.faq_topictitle }} topic image icon' class='list-icon'> <a href='/topics/?q={{topic.faq_topicid}}' aria-label='{{ topic.faq_topictitle }} link current page' class='category-list-title-active'>{{ topic.faq_topictitle }}</a>
            </li>
          {% else %}
            <li class='category-list-item'>
              <img src='{{topic.faq_topicicon.Url}}' alt='{{ topic.faq_topictitle }} topic image icon' class='list-icon'> <a href='/topics/?q={{topic.faq_topicid}}' aria-label='{{ topic.faq_topictitle }} link' class='category-list-title'>{{ topic.faq_topictitle }}</a>
            </li>
          {% endif %}
        {% endif %}
      {% endfor %}
    </ul>
  </div>
  <div class='category-main'>
    <a href='/' class='breadcrumb'
      >Topics<img id='img-next-breadcrumb' alt='next breadcrumb' src='/next-breadcrumb.png'><span style='font-weight: 700;'>{{ topicName }}</span></a
    >
    <h2 class='category-h2' id='topic' style='font-size:28px;margin:48px 0 0'>{{ topicName }}</h2>
    {% if parentArticlesExist == true %}
      <ul class='category-list-ul'>
        {% for article in articlesResult %}
          {% if article.faq_faq_article_Topic_faq_topic.faq_topicid == request.params.q %}
            <li>
              <a href='/articles/?q={{article.faq_articleid}}&t={{request.params.q}}' class='category-a'>{{ article.faq_articletitle }}</a>
            </li>
          {% endif %}
        {% endfor %}
      </ul>
      <hr style='margin: 48px 0;'>
    {% else %}
      <hr style='margin: 48px 0;'>
    {% endif %}
    {% for subtopic in subTopicsResult %}
      <div class='category-section'>
        <h3 class='category-h3'>{{ subtopic.faq_topictitle }}</h3>
        <ul class='category-list-ul'>
          {% for article in articlesResult %}
            {% if subtopic.faq_topictitle == article.faq_faq_article_Topic_faq_topic.faq_topictitle %}
              <li>
                <a href='/articles/?q={{article.faq_articleid}}&t={{request.params.q}}' class='category-a'>{{ article.faq_articletitle }}</a>
              </li>
            {% endif %}
          {% endfor %}
        </ul>
      </div>
      <hr style='margin: 48px 0;'>
    {% endfor %}
  </div>
</div>
